import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def imgs(g,r,c):
    h,w=len(g),len(g[0])
    return [g[r][c],g[h-1-r][c],g[r][w-1-c],g[h-1-r][w-1-c],g[c][w-1-r],g[c][r],g[h-1-c][w-1-r],g[h-1-c][r]]

def f(g):
    h,w=len(g),len(g[0])
    bad={v for i in range(h) for j in range(w) for v in [g[i][j]]
         if v!=g[h-1-i][j] or v!=g[i][w-1-j]}
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if out[i][j] in bad:
                vals=[v for v in imgs(g,i,j) if v not in bad]
                out[i][j]=vals[0]
    return out

print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
print(json.dumps(f(G['Test input'])))

def f(g):
    h,w=len(g),len(g[0])
    breaks=lambda i,j: g[i][j]!=g[h-1-i][j] or g[i][j]!=g[i][w-1-j]
    cols={}
    for i in range(h):
        for j in range(w):
            cols.setdefault(g[i][j],[0,0])
            cols[g[i][j]][0]+=1
            if breaks(i,j): cols[g[i][j]][1]+=1
    bad={c for c,(n,b) in cols.items() if b==n and n>0}  # every cell of this color breaks symmetry
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j] in bad:
                vals=[v for v in imgs(g,i,j) if v not in bad]
                out[i][j]=vals[0]
    return out

print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
print(json.dumps(f(G['Test input'])))

from collections import Counter
for k in ['Demo pair 1 input','Test input']:
    print(k, Counter(v for r in G[k] for v in r).most_common())

def maxsq(g,c):
    h,w=len(g),len(g[0]); best=0
    for i in range(h):
        for j in range(w):
            k=1
            while i+k<=h and j+k<=w and all(g[a][b]==c for a in range(i,i+k) for b in range(j,j+k)):
                k+=1
            best=max(best,k-1)
    return best
for k in ['Demo pair 1 input','Test input']:
    print(k, {c:maxsq(G[k],c) for c in sorted({v for r in G[k] for v in r})})

def f(g):
    h,w=len(g),len(g[0])
    bad={c for c in {v for r in g for v in r} if maxsq(g,c)>max(maxsq(g,c2) for c2 in {v for r in g for v in r} if c2!=c)}
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j] in bad:
                vals=[v for v in imgs(g,i,j) if v not in bad]
                out[i][j]=vals[0]
    return out

