def dihedral_images(g, i, j):
    """The values at the 8 dihedrally-symmetric positions of cell (i, j)."""
    h, w = len(g), len(g[0])
    return [g[i][j], g[h-1-i][j], g[i][w-1-j], g[h-1-i][w-1-j],
            g[j][w-1-i], g[j][i], g[h-1-j][w-1-i], g[h-1-j][i]]

def max_solid_square(g, c):
    """The side of the largest all-c solid square in the grid (0 if none)."""
    h, w = len(g), len(g[0]); best = 0
    for i in range(h):
        for j in range(w):
            k = 1
            while i+k <= h and j+k <= w and all(g[a][b] == c for a in range(i, i+k) for b in range(j, j+k)):
                k += 1
            best = max(best, k-1)
    return best

def restore_symmetry(g):
    """Replace every cell of the one anomalous color (the unique color with a strictly larger solid square than all others) by its symmetric images' value, restoring the grid's mirror/rotational symmetry."""
    colors = {v for r in g for v in r}
    bad = {c for c in colors if max_solid_square(g, c) > max(max_solid_square(g, c2) for c2 in colors if c2 != c)}
